import numpy as npfrom math import sinfrom functools import reducetemperatures = np.random.randint(-20, 40, 10000)mean = temperatures.mean()std = temperatures.std()def greater_than_ten(temperatures):    for temp in temperatures:        yield tempdef plus_sin(x):    return sin(x)+x**2mini_group = []count_groups = 0all_count_groups=0def gen_group(all_temp):    global mini_group    global count_groups    global all_count_groups    for t in all_temp:        mini_group.append(t)        count_groups+=1        if count_groups==30:            all_count_groups += 1            yield mini_group            mini_group = []            count_groups = 0def analyst_group(group):    parameter_anomaly = False    group = np.array(group)    parameter_mean = np.mean(group)    parameter_std = np.std(group)    if abs(parameter_mean)>1 or parameter_std>1:        parameter_anomaly = True    parameter_median = np.median(group)    parameter_min = np.min(group)    parameter_max = np.max(group)    parameters = [parameter_mean, parameter_std, parameter_median, parameter_min, parameter_max]    return parameter_anomaly, parameters[0]groups_parameters = []count_var = 0all_normal_temp = []for temp in greater_than_ten(temperatures):    if temp < -15 or temp > 35:        continue    normal_temp = (temp - mean)/std    all_normal_temp.append(normal_temp)for group in gen_group(all_normal_temp):    anomaly,parameters_mean = analyst_group(group)    count_var = 0    groups_parameters.append((anomaly,parameters_mean))anomaly_groups = list(map(lambda x: x[1],list(filter(lambda x: x[0], groups_parameters))))if len(anomaly_groups)>0:    mean_group_anomaly = reduce(lambda x,y: x+y, anomaly_groups)else:    mean_group_anomaly = 0print("Всего окон: ", all_count_groups)print("Всего аномальных окон: ", len(anomaly_groups))print("Ср. знач.: ", mean_group_anomaly)if len(anomaly_groups)>0:    print("Максимальное: ", max(anomaly_groups))    print("Сумма: ", sum(anomaly_groups))else:    print("Максимальное: ", 0)    print("Сумма: ", 0)